(function(){'use strict';let c=POD_CATALOG,e=POD_ENGINE,$=id=>document.getElementById(id);let category='',family=null,resultLimit=50;
const sourceMoney=(n,currency)=>new Intl.NumberFormat('tr-TR',{style:'currency',currency}).format(n/100);
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
const node=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;};

for(const p of c.providers){const option=node('option',p.name+(c.products.some(x=>x.providerId===p.id)?'':' (katalog yok)'));option.value=p.id;$('provider').append(option);}
function directory(){const query=e.normalize($('providerQuery').value),state=$('providerState').value;const status=p=>['complete','partial'].includes(p.connection?.state)?'connected':c.products.some(x=>x.providerId===p.id)?'snapshot':'discovered';$('providerList').replaceChildren();let count=0;for(const p of c.providers){if((query&&!e.normalize(p.name).includes(query))||(state&&status(p)!==state))continue;count++;const box=node('div'),a=node('a',p.name);a.href=p.verification==='directory-only'?p.directorySource:p.homepage;a.target='_blank';a.rel='noopener noreferrer';const n=c.products.filter(x=>x.providerId===p.id).length;box.append(a,node('small',status(p)==='connected'?(p.connection?.state==='partial'?'Halka açık kategoriler · ':'Doğrudan katalog · ')+n+' ürün':status(p)==='snapshot'?'Elle alınmış kayıt · '+n+' ürün':'Aday kaynak · katalog bağlı değil'));if(n){const b=node('button','Ürünleri göster');b.className='secondary';b.addEventListener('click',()=>{$('provider').value=p.id;category='';$('query').value='';$('material').value='';$('maxPrice').value='';location.hash='';nav();render();$('listing').scrollIntoView?.({behavior:'smooth'});});box.append(b);}else box.append(node('small',p.connection?.blockedReason||'Faaliyet ve resmi site doğrulaması bekliyor'));$('providerList').append(box);}$('providerSummary').textContent=c.providers.length+' aday/platform kaydı · '+c.providers.filter(p=>status(p)==='connected').length+' doğrudan katalog · '+c.providers.filter(p=>status(p)==='snapshot').length+' elle alınmış kaynak · '+count+' sonuç';if(!count)$('providerList').append(node('p','Üretici bulunamadı.'));}
function chooseCategory(id){category=id;resultLimit=50;family=null;for(const key of ['query','provider','material','maxPrice'])$(key).value='';$('sort').value='base';location.hash='';nav();render();}
function nav(){const taxonomy=POD_TAXONOMY.nodes,filter=e.normalize($('categoryQuery').value);$('categories').replaceChildren();$('categorySummary').textContent='15 ana kategori · '+taxonomy.length.toLocaleString('tr')+' ana ve alt kategori';const all=node('button','Tüm ürünler',category===''?'active':'');all.addEventListener('click',()=>chooseCategory(''));$('categories').append(all);const visible=new Set();if(filter)for(const n of taxonomy)if(e.normalize(n.label+' '+n.labelTr+' '+n.path.join(' ')).includes(filter)){let x=n;while(x){visible.add(x.id);x=POD_TAXONOMY_ENGINE.byId.get(x.parentId);}}const counts=new Map();for(const p of c.products){let n=POD_TAXONOMY_ENGINE.byId.get(POD_TAXONOMY_ENGINE.classify(p));while(n){counts.set(n.id,(counts.get(n.id)||0)+1);n=POD_TAXONOMY_ENGINE.byId.get(n.parentId);}}
function branch(parent,target){for(const n of taxonomy.filter(x=>x.parentId===parent)){if(filter&&!visible.has(n.id))continue;const children=POD_TAXONOMY_ENGINE.children.get(n.id)||[],label=n.labelTr+(counts.get(n.id)?' ('+counts.get(n.id)+')':' (0)'),b=node('button',label,n.id===category?'active':'');b.title=n.path.join(' > ');b.setAttribute('aria-pressed',String(n.id===category));b.addEventListener('click',()=>chooseCategory(n.id));if(children.length){const details=node('details'),summary=node('summary');details.open=Boolean(filter)||POD_TAXONOMY_ENGINE.isWithin(category,n.id);summary.append(b);details.append(summary);const sub=node('div',undefined,'category-branch');branch(n.id,sub);details.append(sub);target.append(details);}else target.append(b);}}branch(null,$('categories'));if(filter&&!visible.size)$('categories').append(node('p','Kategori bulunamadı.'));}
function render(){$('listing').hidden=false;$('detail').hidden=true;$('coverage').textContent=c.products.length.toLocaleString('tr')+' fiyat kaydı · '+new Set(c.products.map(p=>p.providerId)).size+' platform · '+POD_TAXONOMY.nodes.length.toLocaleString('tr')+' Etsy kategorisi';$('cards').replaceChildren();renderSearch();}
function productPhoto(p){if(!p.imageUrl)return node('div','Fotoğraf henüz alınmadı','photo-missing');const img=node('img');img.src=p.imageUrl;img.alt=p.title;img.loading='lazy';img.referrerPolicy='no-referrer';img.className='product-photo';img.addEventListener('error',()=>{img.hidden=true;img.parentNode?.append(node('small','Fotoğraf yüklenemedi'));});return img;}
function renderSearch(){
 const max=$('maxPrice').value,records=e.offers(c,{query:$('query').value,category,provider:$('provider').value,material:$('material').value,maxPrice:max===''?null:Number(max),sort:$('sort').value});
 $('searchResults').hidden=false;$('cards').hidden=true;$('heading').textContent=category?(POD_TAXONOMY_ENGINE.byId.get(category)?.path.map(x=>POD_TAXONOMY_ENGINE.translate(x)).join(' › ')||category):$('query').value.trim()?'“'+$('query').value.trim()+'” için platform fiyatları':'Tüm ürünler · Platform fiyatları';$('resultCount').textContent=records.length+' ürün seçeneği · '+new Set(records.map(p=>p.providerId)).size+' platform';$('platformPrices').replaceChildren();$('searchOffers').replaceChildren();
 if(!records.length){const tr=node('tr'),td=node('td','Bu ürün için bağlı kataloglarda sonuç bulunamadı. Katalog henüz bağlı olmayan platformlarda ürün olmadığı anlamına gelmez.');td.colSpan=5;tr.append(td);$('searchOffers').append(tr);}
 for(const p of records.slice(0,resultLimit)){const row=node('tr'),td=text=>{const el=node('td',text);row.append(el);return el;};td(c.providers.find(x=>x.id===p.providerId).name+(p.fulfillmentProvider?' · '+p.fulfillmentProvider:''));const productCell=td();const productLink=node('a');productLink.href=p.sourceUrl;productLink.target='_blank';productLink.rel='noopener noreferrer';productLink.append(productPhoto(p),node('span',p.title));productCell.append(productLink);const priceCell=td();if(!p.sourceVariantId)priceCell.append(node('small',p.includesPrint===false?'Baskısız ürün bedeli':'Başlangıç fiyatı'));if(p.originalMinor>p.baseMinor)priceCell.append(node('del',p.sourceOriginalMinor?sourceMoney(p.sourceOriginalMinor,p.sourceCurrency):money(p.originalMinor)),node('small','İndirim'));priceCell.append(node('strong',p.sourceCurrency&&p.sourceCurrency!=='USD'?sourceMoney(p.sourceMinor,p.sourceCurrency):money(p.baseMinor)));if(p.sourceCurrency&&p.sourceCurrency!=='USD')priceCell.append(node('small','≈ '+money(p.baseMinor)+' · sıralama karşılığı'));priceCell.append(node('small',p.priceBasis));td((p.material||'Materyal bilgisi eksik')+' · '+p.sizes);const link=node('a','Ürüne git ↗','product-link');link.href=p.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';td().append(link);$('searchOffers').append(row);}
 $('searchCaption').textContent=records.length+' eşleşmenin '+Math.min(resultLimit,records.length)+' tanesi gösteriliyor';$('loadMore').hidden=records.length<=resultLimit;
}
function detail(){const def=c.families.find(x=>x.id===family);if(!def){family=null;render();return;}$('listing').hidden=true;$('detail').hidden=false;$('detailTitle').textContent=def.label;$('breadcrumb').textContent=c.categories.find(x=>x.id===def.category).label;$('detailNote').textContent=def.description;$('offers').replaceChildren();for(const p of e.sort(c.products.filter(x=>x.family===family).map(x=>e.quote(x,$('country').value)),$('offerSort').value)){const tr=node('tr'),td=text=>{const el=node('td',text);tr.append(el);return el;};td(c.providers.find(x=>x.id===p.providerId).name+(p.fulfillmentProvider?' · '+p.fulfillmentProvider:'')).append(node('small',p.title));td().append(node('strong',money(p.baseMinor)),node('small',p.priceBasis));td((p.material||'Materyal doğrulanmadı')+' · '+p.sizes);td(p.shippingMinor==null?(p.shippingFrom?.[$('country').value]!=null?money(p.shippingFrom[$('country').value])+' başlangıç; kesin değil':'Adres / varyant gerekli'):money(p.shippingMinor));td(p.totalMinor==null?'Hesaplanamadı':money(p.totalMinor));td((p.production||'Üretim bilinmiyor')+' / '+(p.deliveryDays==null?'Teslimat bilinmiyor':p.deliveryDays+' gün'));const link=node('a','Üreticiye git');link.href=p.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';td().append(link);$('offers').append(tr);}}
function route(){const hash=location.hash.slice(1);if(hash.startsWith('product=')){try{family=decodeURIComponent(hash.slice(8));}catch{family=null;}detail();}else{family=null;render();}}

let suggestionIndex=-1;
function closeSuggestions(){$('searchSuggestions').hidden=true;$('query').setAttribute('aria-expanded','false');$('query').removeAttribute('aria-activedescendant');suggestionIndex=-1;}
function selectSuggestion(label){$('query').value=label;closeSuggestions();resultLimit=50;category='';family=null;$('sort').value='base';location.hash='';nav();render();}
function showSuggestions(){const q=$('query').value.trim();const box=$('searchSuggestions');box.replaceChildren();suggestionIndex=-1;if(q.length<2){closeSuggestions();return;}const labels=[],seen=new Set();const add=label=>{const key=e.normalize(label);if(!seen.has(key)&&labels.length<8){seen.add(key);labels.push(label);}};for(const n of POD_TAXONOMY.nodes){if(e.normalize(n.labelTr).includes(e.normalize(q)))add(n.labelTr);}for(const p of e.offers(c,{query:q,sort:'base'})){add(p.title);if(labels.length>=8)break;}for(const [i,label] of labels.entries()){const option=node('button',label,'search-suggestion');option.type='button';option.id='suggestion-'+i;option.setAttribute('role','option');option.setAttribute('aria-selected','false');option.addEventListener('click',()=>selectSuggestion(label));box.append(option);}box.hidden=!labels.length;$('query').setAttribute('aria-expanded',String(!!labels.length));}
$('query').addEventListener('input',showSuggestions);
$('query').addEventListener('focus',showSuggestions);
$('query').addEventListener('keydown',ev=>{const options=Array.from($('searchSuggestions').children);if(ev.key==='Escape'){closeSuggestions();return;}if($('searchSuggestions').hidden||!options.length)return;if(ev.key==='ArrowDown'||ev.key==='ArrowUp'){ev.preventDefault();suggestionIndex=(suggestionIndex+(ev.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((o,i)=>{o.classList.toggle('selected',i===suggestionIndex);o.setAttribute('aria-selected',String(i===suggestionIndex));});$('query').setAttribute('aria-activedescendant',options[suggestionIndex].id);}else if(ev.key==='Enter'&&suggestionIndex>=0){ev.preventDefault();selectSuggestion(options[suggestionIndex].textContent);}});
document.addEventListener('click',ev=>{if(!$('searchForm').contains(ev.target))closeSuggestions();});
$('searchForm').addEventListener('submit',closeSuggestions);

$('loadMore').addEventListener('click',()=>{resultLimit+=50;renderSearch();});$('searchForm').addEventListener('submit',ev=>{ev.preventDefault();resultLimit=50;family=null;category='';nav();location.hash='';render();});$('query').addEventListener('input',()=>{resultLimit=50;family=null;category='';nav();if(location.hash.startsWith('#product='))location.hash='';render();});for(const id of ['provider','material','maxPrice','sort'])$(id).addEventListener('change',()=>{resultLimit=50;render();});for(const id of ['country','offerSort'])$(id).addEventListener('change',detail);$('back').addEventListener('click',()=>{location.hash='';render();});$('reset').addEventListener('click',()=>{category='';for(const id of ['query','provider','material','maxPrice'])$(id).value='';$('sort').value='base';nav();render();});$('categoryQuery').addEventListener('input',nav);$('expandCategories').addEventListener('click',()=>{for(const d of document.querySelectorAll('#categories details'))d.open=true;});$('collapseCategories').addEventListener('click',()=>{for(const d of document.querySelectorAll('#categories details'))d.open=false;});window.addEventListener('hashchange',route);$('providerQuery').addEventListener('input',directory);$('providerState').addEventListener('change',directory);nav();route();directory();async function refreshView(){if(location.protocol!=='http:'&&location.protocol!=='https:')return;try{const response=await fetch('/api/catalog',{cache:'no-store'});if(!response.ok)return;const next=await response.json();if(!Array.isArray(next.products))return;c=next;nav();route();const info=await fetch('/api/status',{cache:'no-store'}).then(r=>r.json());$('refreshStatus').textContent=Object.entries(info.platforms||{}).map(([id,p])=>{const name=c.providers.find(v=>v.id===id)?.name||id;return name+': '+(p.state==='updating'?'yenileniyor':p.state==='error'?'son kontrol başarısız; önceki fiyatlar':p.lastSuccess?new Date(p.lastSuccess).toLocaleTimeString('tr-TR'):'kontrol bekliyor')+' ('+p.intervalMinutes+' dk)';}).join(' · ');}catch{}}if(typeof setInterval==='function'){refreshView();setInterval(refreshView,60000);}})();



